    static readonly JsonSerializerOptions Json = new(JsonSerializerDefaults.Web); public static void Map(WebApplication app) { app.MapPost("/agent/v1/execution-event-batches", Ingest).RequirePermission("agent:heartbeat"); app.MapGet("/agent/v1/execution-policy", AgentPolicy).RequirePermission("agent:heartbeat"); app.MapPost("/agent/v1/execution-policy:acknowledge", Acknowledge).RequirePermission("agent:heartbeat"); app.MapGet("/api/v1/execution-events", Search).RequirePermission("execution:read"); app.MapGet("/api/v1/execution-events/{id:guid}", Get).RequirePermission("execution:details:read"); app.MapGet("/api/v1/execution-entities/{entity}/history", History).RequirePermission("execution:details:read"); app.MapGet("/api/v1/endpoints/{endpoint:guid}/execution-timeline", Timeline).RequirePermission("execution:read"); app.MapGet("/api/v1/processes/{entity}/execution", ProcessView).RequirePermission("execution:details:read"); app.MapGet("/api/v1/endpoints/{endpoint:guid}/execution-telemetry-health", Health).RequirePermission("execution:health:read"); app.MapGet("/api/v1/execution-telemetry/policies", Policies).RequirePermission("execution:policy:manage"); app.MapPost("/api/v1/execution-telemetry/policies", CreatePolicy).RequirePermission("execution:policy:manage"); app.MapPost("/api/v1/execution-telemetry/policies/{id:guid}:assign", Assign).RequirePermission("execution:policy:manage"); app.MapGet("/api/v1/endpoints/{endpoint:guid}/execution-policy", Effective).RequirePermission("execution:policy:manage"); app.MapPost("/api/v1/execution-exports", CreateExport).RequirePermission("execution:export"); app.MapGet("/api/v1/execution-exports/{id:guid}", ExportStatus).RequirePermission("execution:export"); app.MapGet("/api/v1/execution-exports/{id:guid}/manifest", ExportManifest).RequirePermission("execution:export"); app.MapGet("/api/v1/execution-exports/{id:guid}/content", ExportContent).RequirePermission("execution:export"); app.MapPost("/api/v1/execution-exports/{id:guid}/