    static async Task<IResult> Ingest(HttpContext c, IExecutionTelemetryRepository r, CancellationToken ct) { if (!c.Request.IsHttps || c.Request.ContentLength is > 1048576) return Problem(c, "EXECUTION_BATCH_SIZE", "Batch exceeds compressed limit.", 413); if (c.Items["principal"] is not PrincipalContext { Type: "agent" } principal) return Results.Unauthorized(); if (!long.TryParse(c.Request.Headers["X-Uncompressed-Length"], out var expected) || expected is < 1 or > 4194304 || !string.Equals(c.Request.Headers.ContentEncoding.FirstOrDefault(), "gzip", StringComparison.OrdinalIgnoreCase)) return Problem(c, "EXECUTION_COMPRESSION_REQUIRED", "Bounded gzip is required.", 400); try { await using var gzip = new GZipStream(c.Request.Body, CompressionMode.Decompress); await using var memory = new MemoryStream(); var buffer = new byte[8192]; int read; long total = 0; while ((read = await gzip.ReadAsync(buffer, ct)) > 0) { total += read; if (total > 4194304) return Problem(c, "EXECUTION_DECOMPRESSED_SIZE", "Decompressed batch exceeds limit.", 413); await memory.WriteAsync(buffer.AsMemory(0, read), ct); } if (total != expected) return Problem(c, "EXECUTION_LENGTH_MISMATCH", "Length mismatch.", 400); var batch = JsonSerializer.Deserialize<ExecutionEventBatch>(memory.ToArray(), Json); if (batch is null || batch.Events.Count is < 1 or > 1000) return Problem(c, "EXECUTION_BATCH_INVALID", "Invalid batch.", 400); var ids = principal.Subject.Split(':'); if (ids.Length != 2 || !Guid.TryParse(ids[0], out var endpoint) || !Guid.TryParse(ids[1], out var agent) || batch.EndpointId != endpoint || batch.AgentId != agent) return Results.Unauthorized(); var hash = Convert.ToHexString(SHA256.HashData(JsonSerializer.SerializeToUtf8Bytes(batch.Events, Json))).ToLowerInvariant(); if (!CryptographicOperations.FixedTimeEquals(Encoding.ASCII.GetBytes(hash), Encoding.ASCII.GetBytes(batch.ContentSha256.ToLowerInvariant()))) return Problem(c, "EXECUTION_INTEGRITY_INVALID", "Integrity failed.", 400); ExecutionTelemetryHealth? health = null; if (c.Request.Headers["X-Execution-Health"].FirstOrDefault() is { Length: > 0 } encoded) try { health = JsonSerializer.Deserialize<ExecutionTelemetryHealth>(Convert.FromBase64String(encoded), Json); } catch (FormatException) { } if (health is null || health.EndpointId != endpoint) return Problem(c, "EXECUTION_HEALTH_INVALID", "A valid bounded health snapshot is required.", 400); return Results.Ok((await r.IngestAsync(principal.TenantId, batch, health, ct)).Acknowledgement); } catch (InvalidDataException) { return Problem(c, "EXECUTION_COMPRESSION_INVALID", "Compressed body is invalid.", 400); } catch (JsonException) { return Problem(c, "EXECUTION_BATCH_INVALID", "Batch JSON is invalid.", 400); } }
    static async Task<IResult> Search(HttpContext c, IExecutionProjection p, CancellationToken ct) => Results.Ok(Envelope(c, await p.SearchAsync(Tenant(c), Query(c.Request), ct))); static async Task<IResult> Get(Guid id, HttpContext c, IExecutionTelemetryRepository r, CancellationToken ct) => await r.GetAsync(Tenant(c), id, ct) is { } value ? Results.Ok(Envelope(c, value)) : Results.NotFound(); static async Task<IResult> History(string entity, HttpContext c, IExecutionTelemetryRepository r, CancellationToken ct) { if (!Guid.TryParse(c.Request.Query["endpointId"], out var endpoint) || entity.Length != 64 || !ExecutionSafety.ValidHash(entity)) return Problem(c, "EXECUTION_HISTORY_INVALID", "Endpoint and valid entity identity are required.", 400); return Results.Ok(Envelope(c, await r.EntityHistoryAsync(Tenant(c), endpoint, entity, 500, ct))); }
    static async Task<IResult> Timeline(Guid endpoint, HttpContext c, IExecutionProjection p, CancellationToken ct) => Results.Ok(Envelope(c, await p.SearchAsync(Tenant(c), Query(c.Request) with { EndpointId = endpoint }, ct))); static async Task<IResult> ProcessView(string entity, HttpContext c, IExecutionProjection p, CancellationToken ct) { if (entity.Length != 64 || !ExecutionSafety.ValidHash(entity)) return Problem(c, "PROCESS_IDENTITY_INVALID", "Process entity identity is invalid.", 400); var tenant = Tenant(c); var query = Query(c.Request); var source = await p.SearchAsync(tenant, query with { SourceProcess = entity }, ct); var target = await p.SearchAsync(tenant, query with { TargetProcess = entity }, ct); var items = source.Items.Concat(target.Items).DistinctBy(x => x.EventId).OrderByDescending(x => x.ObservedAt).Take(Math.Clamp(query.PageSize, 1, 500)).ToArray(); return Results.Ok(Envelope(c, new ExecutionEventPage(items, null))); }
    static async Task<IResult> Health(Guid endpoint, HttpContext c, IExecutionTelemetryRepository r, CancellationToken ct) => await r.HealthAsync(Tenant(c), endpoint, ct) is { } value ? Results.Ok(Envelope(c, value)) : Results.NotFound(); static async Task<IResult> Policies(HttpContext c, IExecutionPolicyRepository p, CancellationToken ct) => Results.Ok(Envelope(c, await p.ListAsync(Tenant(c), ct))); static async Task<IResult> CreatePolicy(PolicyCreate input, HttpContext c, IExecutionPolicyRepository p, CancellationToken ct) { var errors = ExecutionSafety.Validate(input.Policy); if (errors.Count > 0) return Results.ValidationProblem(errors.ToDictionary()); var principal = (PrincipalContext)c.Items["principal"]!; var value = await p.CreateAsync(principal.TenantId, principal.Subject, input.Name, input.Policy, ct); return Results.Created($"/api/v1/execution-telemetry/policies/{value.Id}", Envelope(c, value)); }
    static async Task<IResult> Assign(Guid id, PolicyAssign input, HttpContext c, IExecutionPolicyRepository p, CancellationToken ct) { var principal = (PrincipalContext)c.Items["principal"]!; await p.AssignAsync(principal.TenantId, id, input.EndpointId, principal.Subject, ct); return Results.NoContent(); }
    static async Task<IResult> Effective(Guid endpoint, HttpContext c, IExecutionPolicyRepository p, CancellationToken ct) => Results.Ok(Envelope(c, await p.EffectiveAsync(Tenant(c), endpoint, ct))); static async Task<IResult> AgentPolicy(HttpContext c, IExecutionPolicyRepository p, CancellationToken ct) { var principal = (PrincipalContext)c.Items["principal"]!; var ids = principal.Subject.Split(':'); return ids.Length == 2 && Guid.TryParse(ids[0], out var endpoint) ? Results.Ok(await p.EffectiveAsync(principal.TenantId, endpoint, ct)) : Results.Unauthorized(); }
    static async Task<IResult> Acknowledge(HttpContext c, ExecutionPolicyAcknowledgement ack, IExecutionPolicyRepository p, CancellationToken ct) { var principal = (PrincipalContext)c.Items["principal"]!; var ids = principal.Subject.Split(':'); if (ids.Length != 2 || !Guid.TryParse(ids[0], out var endpoint)) return Results.Unauthorized(); if (ack.PolicyId != Guid.Empty) await p.AcknowledgeAsync(principal.TenantId, endpoint, ack, ct); return Results.Accepted(); }
    static async Task<IResult> CreateExport(ExecutionExportCreateRequest input, HttpContext c, IExecutionExportRepository r, CancellationToken ct) { if (input.Format is not ("jsonl" or "csv") || input.MaximumRecords is < 1 or > 10000) return Problem(c, "EXECUTION_EXPORT_INVALID", "Invalid bounded export.", 400); var principal = (PrincipalContext)c.Items["principal"]!; var job = await r.CreateAsync(principal.TenantId, principal.Subject, input, ct); return Results.Accepted($"/api/v1/execution-exports/{job.Id}", Envelope(c, job)); }
    static async Task<IResult> ExportStatus(Guid id, HttpContext c, IExecutionExportRepository r, CancellationToken ct) => await r.GetAsync(Tenant(c), id, ct) is { } job ? Results.Ok(Envelope(c, job)) : Results.NotFound(); static async Task<IResult> ExportManifest(Guid id, HttpContext c, IExecutionExportRepository r, IObjectStorage o, CancellationToken ct) => await r.GetAsync(Tenant(c), id, ct) is { State: FileExportState.Completed } job ? Results.Stream(await o.DownloadAsync(job.TenantId, job.ManifestObjectId.ToString("D"), ct), "application/json") : Results.NotFound(); static async Task<IResult> ExportContent(Guid id, HttpContext c, IExecutionExportRepository r, IObjectStorage o, CancellationToken ct) => await r.GetAsync(Tenant(c), id, ct) is { State: FileExportState.Completed } job ? Results.Stream(await o.DownloadAsync(job.TenantId, job.OutputObjectId.ToString("D"), ct), job.Format == "csv" ? "text/csv" : "application/x-ndjson") : Results.NotFound(); static async Task<IResult> DownloadUrl(Guid id, FileExportDownloadRequest input, HttpContext c, IExecutionExportRepository r, PlatformOptions options, CancellationToken ct) { var tenant = Tenant(c); if (await r.GetAsync(tenant, id, ct) is not { State: FileExportState.Completed }) return Results.NotFound(); var expires = DateTimeOffset.UtcNow.AddSeconds(Math.Clamp(input.ExpiresInSeconds, 5, 300)); return Results.Ok(Envelope(c, new { url = $"{c.Request.Scheme}://{c.Request.Host}/api/v1/execution-exports/{id}/download?token={Uri.EscapeDataString(FileExportDownloadToken.Create(tenant, id, expires, options.JwtSigningKey))}", expiresAt = expires })); }
    static async Task<IResult> SignedDownload(Guid id, string token, PlatformOptions options, IExecutionExportRepository r, IObjectStorage s, CancellationToken ct) { if (!FileExportDownloadToken.TryValidate(token, options.JwtSigningKey, out var tenant, out var export) || export != id || await r.GetAsync(tenant, id, ct) is not { State: FileExportState.Completed } job) return Results.NotFound(); return Results.Stream(await s.DownloadAsync(tenant, job.OutputObjectId.ToString("D"), ct), job.Format == "csv" ? "text/csv" : "application/x-ndjson"); }
    static ExecutionSearchRequest Query(HttpRequest r) { Guid? endpoint = Guid.TryParse(r.Query["endpointId"], out var e) ? e : null; int? sourcePid = int.TryParse(r.Query["sourcePid"], out var sp) ? sp : null; int? targetPid = int.TryParse(r.Query["targetPid"], out var tp) ? tp : null; int? thread = int.TryParse(r.Query["threadId"], out var tid) ? tid : null; uint? protection = ParseUInt(r.Query["memoryProtection"]); ulong? start = ParseULong(r.Query["startAddress"]); bool? executable = bool.TryParse(r.Query["executableMemory"], out var ex) ? ex : null; DateTimeOffset? from = DateTimeOffset.TryParse(r.Query["from"], out var f) ? f : null; DateTimeOffset? to = DateTimeOffset.TryParse(r.Query["to"], out var t) ? t : null; ExecutionEventKind? kind = Enum.TryParse<ExecutionEventKind>(r.Query["kind"], true, out var k) ? k : null; int size = int.TryParse(r.Query["pageSize"], out var p) ? Math.Clamp(p, 1, 500) : 100; string? V(string name) => string.IsNullOrWhiteSpace(r.Query[name]) ? null : r.Query[name].ToString(); return new(endpoint, V("sourceProcess"), V("targetProcess"), sourcePid, targetPid, V("operation"), V("handleType"), V("accessFlag"), protection, executable, thread, start, V("sectionIdentity"), from, to, V("quality"), kind, size, V("cursor")); }
    static uint? ParseUInt(string? value) { if (value is null) return null; if (value.StartsWith("0x", StringComparison.OrdinalIgnoreCase) && uint.TryParse(value[2..], System.Globalization.NumberStyles.HexNumber, null, out var hex)) return hex; return uint.TryParse(value, out var number) ? number : null; }
    static ulong? ParseULong(string? value) { if (value is null) return null; if (value.StartsWith("0x", StringComparison.OrdinalIgnoreCase) && ulong.TryParse(value[2..], System.Globalization.NumberStyles.HexNumber, null, out var hex)) return hex; return ulong.TryParse(value, out var number) ? number : null; }
    static string Tenant(HttpContext c) => c.Items["tenant"]!.ToString()!; static object Envelope(HttpContext c, object value) => new { traceId = c.TraceIdentifier, data = value }; static IResult Problem(HttpContext c, string code, string message, int status) => Results.Json(new ApiError(code, message, status, c.TraceIdentifier), statusCode: status); public sealed record PolicyCreate(string Name, ExecutionTelemetryPolicy Policy); public sealed record PolicyAssign(Guid? EndpointId);
